import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts before it is full.

    A queue with capacity `cap` is created and each element of xs is put
    in order without blocking. Counting stops at the first put that finds
    the queue full. Nothing is ever taken out of the queue.

    A capacity of zero or less accepts nothing, even though
    queue.Queue treats maxsize <= 0 as unbounded.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_more_items_than_capacity() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_exact_capacity() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_zero_capacity_accepts_nothing() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity_accepts_nothing() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_duplicates_are_all_counted() -> None:
    assert accepted(3, [5, 5, 5, 5]) == 3


@pytest.mark.parametrize("cap", range(0, 6))
def test_equals_min_of_cap_and_length(cap: int) -> None:
    xs = [1, 2, 3, 4]
    assert accepted(cap, xs) == min(cap, len(xs))


def test_does_not_mutate_input() -> None:
    xs = [1, 2, 3]
    accepted(2, xs)
    assert xs == [1, 2, 3]
